class Solution:
    def minGroups(self, words: List[str]) -> int:
        def minrot(s):
            if not s:
                return ''
            cands = [s[i:] + s[:i] for i in range(len(s))]
            return min(cands)
        seen = set()
        for w in words:
            seen.add(minrot(w[0::2]) + '|' + minrot(w[1::2]))
        return len(seen)

