class Solution {
public:
    string minrot(const string& s) {
        if (s.empty()) return s;
        string best = s;
        for (int i = 1; i < (int)s.size(); i++)
            best = min(best, s.substr(i) + s.substr(0, i));
        return best;
    }
    int minGroups(vector<string>& words) {
        unordered_set<string> seen;
        for (auto& w : words) {
            string E, O;
            for (int i = 0; i < (int)w.size(); i++)
                (i % 2 ? O : E) += w[i];
            seen.insert(minrot(E) + "|" + minrot(O));
        }
        return seen.size();
    }
};

