class Solution {
    private String minrot(String s) {
        if (s.isEmpty()) return s;
        String best = s;
        for (int i = 1; i < s.length(); i++) {
            String cand = s.substring(i) + s.substring(0, i);
            if (cand.compareTo(best) < 0) best = cand;
        }
        return best;
    }
    public int minGroups(String[] words) {
        Set<String> seen = new HashSet<>();
        for (String w : words) {
            StringBuilder e = new StringBuilder(), o = new StringBuilder();
            for (int i = 0; i < w.length(); i++)
                (i % 2 == 0 ? e : o).append(w.charAt(i));
            seen.add(minrot(e.toString()) + "|" + minrot(o.toString()));
        }
        return seen.size();
    }
}

