                        k = j - i - 1
                    i = f[i]
                if cj != ss[k + i + 1]:
                    if cj < ss[k]:
                        k = j
                    f[j - k] = -1
                else:
                    f[j - k] = i + 1
            return ss[k:k + n]
        seen = set()
        for w in words:
            seen.add(minrot(w[0::2]) + '|' + minrot(w[1::2]))
        return len(seen)

